import { describe, expect, it } from 'vitest';
import { computeDay } from '../../src/core/engine';
import type { CalculationPrefs, MethodId, PrayerSlot } from '../../src/core/types';

/**
 * Values recorded from the Aladhan API on 27 October 2026, with each request naming the
 * coordinate, the time zone and Aladhan's method id. They are stored here rather than
 * fetched, so the test never touches the network. Aladhan is a separate implementation
 * from adhan-js, which is the point: these catch a library wiring mistake that a fixture
 * generated by adhan-js cannot. Five minutes is allowed because the two implementations
 * do not use identical method offsets or rounding: on 10 April 2026 the extension's
 * Moonsighting Dhuhr is 13:07 against Aladhan's 13:02, and its MWL Asr is 16:46 against
 * 16:44. The phone's exact values remain the golden fixtures in engine.test.ts. This
 * file is a broad outside sanity check, not a replacement for those.
 */
