const slots: PrayerSlot[] = ['fajr', 'sunrise', 'dhuhr', 'asr', 'maghrib', 'isha'];

function minutes(value: string): number {
  const [hours, mins] = value.split(':').map(Number);
  return (hours ?? 0) * 60 + (mins ?? 0);
}

function localMinutes(at: Date, timeZone: string): number {
  const text = new Intl.DateTimeFormat('en-GB', {
    timeZone,
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(at);
  return minutes(text);
}

describe('independent Aladhan fixtures', () => {
  for (const fixture of fixtures) {
    it(`agrees with Aladhan for ${fixture.method} on ${fixture.date}`, () => {
      const prefs: CalculationPrefs = {
        method: fixture.method,
        madhab: 'shafii',
        timeZone: fixture.timeZone,
      };
      const day = computeDay(fixture.place, fixture.date, prefs);
      for (const slot of slots) {
        const actual = localMinutes(day.times[slot], fixture.timeZone);
        const expected = minutes(fixture.times[slot]);
        expect(Math.abs(actual - expected), `${slot} was ${actual}, expected ${expected}`).toBeLessThanOrEqual(5);
      }
    });
  }
});
